/*
[P₁  0
         0   P₃][    L        0
                 P₃ᵀCP₂ᵀU⁻¹  -L̃][U  L⁻¹P₁ᵀB
                                 0     Ũ   ][P₂   0
                                             0   I_2]
        where
        P_i: ℝ^(2×2)
        B: ℝ^(2×2)
        C: ℝ^(2×2)
        L: ℝ^(2×2)
        L̃: ℝ^(2×2)
        U: ℝ^(2×2)
        Ũ: ℝ^(2×2)
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 4, 4> ret;

    heartlib(
        const std::vector<Eigen::Matrix<double, 2, 2>> & P,
        const Eigen::Matrix<double, 2, 2> & B,
        const Eigen::Matrix<double, 2, 2> & C,
        const Eigen::Matrix<double, 2, 2> & L,
        const Eigen::Matrix<double, 2, 2> & L̃,
        const Eigen::Matrix<double, 2, 2> & U,
        const Eigen::Matrix<double, 2, 2> & Ũ)
    {
        const long dim_0 = P.size();
        Eigen::Matrix<DT, 4, 4> ret_0;
        ret_0 << P.at(1-1), MatrixD::Zero(2, 2),
        MatrixD::Zero(2, 2), P.at(3-1);
        Eigen::Matrix<DT, 4, 4> ret_1;
        ret_1 << L, MatrixD::Zero(2, 2),
        P.at(3-1).transpose() * C * P.at(2-1).transpose() * U.inverse(), -L̃;
        Eigen::Matrix<DT, 4, 4> ret_2;
        ret_2 << U, (to_double(L)).colPivHouseholderQr().solve(to_double(P.at(1-1).transpose())) * B,
        MatrixD::Zero(2, 2), Ũ;
        Eigen::Matrix<DT, 4, 4> ret_3;
        ret_3 << P.at(2-1), MatrixD::Zero(2, 2),
        MatrixD::Zero(2, 2), MatrixD::Identity(2, 2);
        ret = ret_0 * ret_1 * ret_2 * ret_3;
    }
};

