function output = heartlib(P, B, C, L, L_tilde, U, U_tilde)
% output = heartlib(P, B, C, L, L̃, U, Ũ)
%
%    [P₁  0
%             0   P₃][    L        0
%                     P₃ᵀCP₂ᵀU⁻¹  -L̃][U  L⁻¹P₁ᵀB
%                                     0     Ũ   ][P₂   0
%                                                 0   I_2]
%            where
%            P_i: ℝ^(2×2)
%            B: ℝ^(2×2)
%            C: ℝ^(2×2)
%            L: ℝ^(2×2)
%            L̃: ℝ^(2×2)
%            U: ℝ^(2×2)
%            Ũ: ℝ^(2×2)
    dim_0 = size(P, 1);
    assert( isequal(size(P), [dim_0, 2, 2]) );
    assert( isequal(size(B), [2, 2]) );
    assert( isequal(size(C), [2, 2]) );
    assert( isequal(size(L), [2, 2]) );
    assert( isequal(size(L_tilde), [2, 2]) );
    assert( isequal(size(U), [2, 2]) );
    assert( isequal(size(U_tilde), [2, 2]) );

    ret_0 = [[squeeze(P(1,:,:)), zeros(2, 2)]; [zeros(2, 2), squeeze(P(3,:,:))]];
    ret_1 = [[L, zeros(2, 2)]; [squeeze(P(3,:,:))' * C * squeeze(P(2,:,:))' * inv(U), -L_tilde]];
    ret_2 = [[U, ((L)\(squeeze(P(1,:,:))')) * B]; [zeros(2, 2), U_tilde]];
    ret_3 = [[squeeze(P(2,:,:)), zeros(2, 2)]; [zeros(2, 2), speye(2)]];
    ret = ret_0 * ret_1 * ret_2 * ret_3;
    output.ret = ret;
end

